kotlin:
package sample.catalog

@Target(AnnotationTarget.CLASS)
annotation class DisplayName(val value: String)

@DisplayName("Product")
data class Product(val code: String, val price: Int) {
    fun label(currency: String = "USD"): String = when {
        price == 0 -> "$code is free"
        price < 10 -> "$code: $price $currency (sale)"
        else -> "$code: $price $currency"
    }
}

class Catalog(private val products: List<Product>) {
    fun search(prefix: String): List<String> {
        return products
            .filter { item -> item.code.startsWith(prefix, ignoreCase = true) }
            .sortedBy { it.price }
            .map { "  ${it.label()}" }
    }
}

fun main() {
    val goods = listOf(Product("Pen", 3), Product("Pencil", 0))
    Catalog(goods).search("pe").forEach { println(it) }
}

